383	\begin{lemma}[Formalization support for the Boolean Fourier transform]
384		\label{lem:boolean-fourier-transform}
385		\lean{MIPStarRE.QPBT.booleanCharacter, MIPStarRE.QPBT.operatorFourier}
386		\lean{MIPStarRE.QPBT.operatorFourier_isHermitian}
387		\lean{MIPStarRE.QPBT.operatorFourier_inversion}
388		\lean{MIPStarRE.QPBT.sum_operatorFourier_mul_operatorFourier}
389		\lean{MIPStarRE.QPBT.sum_operatorFourier_sq}
390		\lean{MIPStarRE.QPBT.sum_operatorFourier_sq_eq_one}
391		\leanok
392		\uses{def:povm-conventions}
393		This is not a named statement of \cite{Natarajan2017Linearity}; it isolates
394		the finite Fourier identities used in the proof given there for
395		Theorem~\ref{thm:linearity}. Write $\chi_u(a) = (-1)^{u \cdot a}$ for
396		$u, a \in \F_2^t$ and, for a family $\{O(a)\}_{a \in \F_2^t}$ of operators,
397		set $\widehat{O}^u = \E_a \, \chi_u(a) \, O(a)$. Each $\widehat{O}^u$ is
398		Hermitian when every $O(a)$ is, and for two such families $A$ and $B$,
399		\[
400			O(a) = \sum_u \chi_u(a) \, \widehat{O}^u ,
401			\qquad
402			\sum_u \widehat{A}^u \, \widehat{B}^u = \E_a \, A(a) B(a) ;
403		\]
404		taking $B = A$ gives $\sum_u (\widehat{O}^u)^2 = \E_a \, O(a)^2$ for a
405		single family $O$. If every $O(a)$ is a binary observable, then
406		$\sum_u (\widehat{O}^u)^2 = \Id$.
407	\end{lemma}
408	\begin{proof}
